// The `nook/ui` module: the elements a mod's views return. Generated by openNook; do not edit.
//
// Elements are descriptions. openNook draws them natively (Rune) and springs every change
// between renders: give an element an `.id()` so it moves and resizes instead of being
// replaced. Sizes are in points.

/** "#rgb", "#rrggbb", "#rrggbbaa", or a theme token: "fg", "muted", "faint", "bg", "surface",
 *  "raised", "border", "accent", "green", "yellow", "red", "blue", "purple", "orange". */
export type Color = string;

export interface Cx {
  /** Render this mod again (after changing something its views read). */
  notify(): void;
  timer: {
    /** Calls `f` every `ms` (at least 50). Returns a function that stops it. */
    every(ms: number, f: (cx: Cx) => void): () => void;
    /** Calls `f` once after `ms`. Returns a function that cancels it. */
    after(ms: number, f: (cx: Cx) => void): () => void;
  };
  /** Runs an async function; a rejection is reported in the mod's .error file. */
  spawn(f: (cx: Cx) => Promise<void>): void;
}

export interface Element {
  /** Names the element: it animates between renders instead of being replaced. */
  id(key: string | number): this;
  child(c: Element | string | number | null | undefined | false): this;
  children(list: (Element | string | number | null | undefined | false)[]): this;
  /** `f(this)` when `cond`, else unchanged. */
  when(cond: unknown, f: (el: this) => this | void): this;

  w(points: number): this;
  h(points: number): this;
  size(points: number): this;
  w_full(): this;
  h_full(): this;
  size_full(): this;
  min_w(points: number): this;
  max_w(points: number): this;
  min_h(points: number): this;
  max_h(points: number): this;
  /** Take the free space along the parent's direction. */
  flex_1(): this;
  grow(factor?: number): this;
  /** Never shrink below the content. */
  flex_none(): this;
  shrink(factor?: number): this;

  p(points: number): this;
  px(points: number): this;
  py(points: number): this;
  pt(points: number): this;
  pr(points: number): this;
  pb(points: number): this;
  pl(points: number): this;
  gap(points: number): this;
  /** Places the element over its parent's content at these insets (null leaves a side free). */
  pin(left?: number | null, top?: number | null, right?: number | null, bottom?: number | null): this;
  /** Covers the whole parent, under the siblings that follow it (a backdrop, a shader). */
  absolute_fill(): this;

  items_start(): this;
  items_center(): this;
  items_end(): this;
  justify_start(): this;
  justify_center(): this;
  justify_end(): this;
  justify_between(): this;

  bg(color: Color): this;
  /** A vertical gradient over the background, top to bottom. */
  gradient(top: Color, bottom: Color): this;
  rounded(radius: number): this;
  rounded_full(): this;
  border(width: number, color: Color): this;
  opacity(o: number): this;
  shadow(y: number, blur: number, color: Color): this;
  /** Clip children to this element's rounded rect. */
  clip(): this;
  hover_bg(color: Color): this;
  cursor_pointer(): this;

  /** Text elements only. */
  text_size(points: number): this;
  text_color(color: Color): this;
  font_weight(weight: number): this;
  font_medium(): this;
  font_semibold(): this;
  font_bold(): this;
  font_mono(): this;
  /** Digits of equal width, for times and counters that change. */
  tabular_nums(): this;
  truncate(): this;
  line_clamp(lines: number): this;
  text_center(): this;
  text_right(): this;
  /** Icons (and text): the color they draw in. */
  color(color: Color): this;

  /** This element's spring for layout changes: duration in seconds, bounce 0–1. */
  spring(duration: number, bounce?: number): this;
  /** How the element appears and disappears. */
  enter(kind: "fade" | "scale" | "blur" | "slide"): this;
  /** Pulses opacity forever (a live dot), period in seconds. */
  pulse(period?: number): this;
  /** Spins forever (a spinner icon), period in seconds. */
  spin(period?: number): this;
  scale(factor: number): this;
  offset(x: number, y: number): this;
  /** Shader elements: frames a second (default 30; 0 draws one still frame). */
  fps(n: number): this;

  on_click(f: (event: {}, cx: Cx) => void): this;
  on_hover(f: (hovered: boolean, cx: Cx) => void): this;
  /** Keys while this element, or a text field inside it, has the keyboard. Keys a field types
   *  into itself (letters, arrows, Backspace) stay the field's; Return submits it and Escape
   *  leaves it. */
  on_key_down(f: (event: KeyEvent, cx: Cx) => void): this;

  /** Scrolls the children vertically when they're taller than this element. Needs a bounded
   *  height (`h`, or `max_h` to grow until then) and an `.id()`. A two-finger swipe that starts
   *  over it scrolls it instead of changing the page. No visible scrollbar. */
  overflow_y_scroll(): this;
  /** `overflow_y_scroll()`, as herdr (and GPUI) spell it. */
  overflow_y_scrollbar(): this;
  /** A scrolling element that opens at its bottom and follows it as content arrives (a chat). */
  stick_bottom(): this;

  /** Text fields: the placeholder's color (default "faint"). */
  placeholder_color(color: Color): this;
}

/** What an `on_key_down` handler receives. */
export interface KeyEvent {
  /** The key: "a", "enter", "escape", "tab", "up", "f5", … */
  key: string;
  /** The whole chord, modifiers first: "cmd-shift-s", "escape". */
  keystroke: string;
  /** The character this key would type, when it types one. */
  key_char?: string | null;
  modifiers: { cmd: boolean; shift: boolean; alt: boolean; ctrl: boolean };
}

/**
 * A text field's state, made once and kept on the view: in `init` or a handler, never in a
 * render (that throws: a render would make a new field every time). The text lives in openNook,
 * so it survives every render and typing never waits on the mod. Show it with
 * `Input.new(state)`.
 *
 * ```js
 * init(props, cx) {
 *   this.field = InputState.new({ placeholder: "New reminder" });
 *   this.field.on("submit", (_, cx) => { add(this.field.value()); this.field.set_value(""); cx.notify(); });
 * }
 * expanded() { return Input.new(this.field).flex_1().h(32).px(10).rounded(8).bg("surface"); }
 * ```
 *
 * Focusing a field (a click, or `focus()`) gives the island the keyboard without bringing
 * openNook forward; the island stays open while someone types, even with the pointer
 * elsewhere. Escape, a click in another app, or the island closing takes it away again.
 */
export interface InputState {
  readonly id: number;
  /** The text now. */
  value(): string;
  /** Replaces the text; no `change` follows. */
  set_value(value: string): void;
  set_placeholder(text: string): void;
  /** Draws the text as a password. */
  set_masked(masked: boolean): void;
  /** Moves the keyboard onto the field, while its page is open. */
  focus(): void;
  /** Takes the keyboard off the field. */
  blur(): void;
  is_focused(): boolean;
  /** `change` on every edit (`{ value }`), `submit` on Return, `focus`, `blur`. */
  on(event: "change" | "submit" | "focus" | "blur", handler: (event: { value?: string }, cx: Cx) => void): boolean;
  /** Forgets the field; using it afterwards does nothing. */
  release(): boolean;
}
export const InputState: {
  new: (options?: { placeholder?: string; value?: string }) => InputState;
};
/** A single-line text field over an `InputState`. Style it like any element: its text with
 *  text_size/text_color/font_*, its box with bg/rounded/border/px/h. */
export const Input: { new: (state: InputState) => Element };
/** `Input.new(state)`, in the lower-case style of the other elements. */
export function input(state: InputState): Element;

/** A box whose children stack vertically. */
export function div(): Element;
export function col(): Element;
export function v_flex(): Element;
/** A box whose children sit side by side, vertically centered. */
export function row(): Element;
export function h_flex(): Element;
export function text(s: string | number): Element;
/** A built-in icon (AGENTS.md lists them), or "./file.svg" from the mod's folder. */
export function icon(name: string, size?: number): Element;
/**
 * An image filling its box (set w/h): "https://…", an absolute path, "./file.png" from the
 * mod's folder, "data:image/png;base64,…", or "app:<bundle id>" for an app's icon.
 */
export function image(src: string): Element;
/** Free space in a row or column. */
export function spacer(): Element;
/**
 * A Metal fragment shader from the mod's folder ("./scene.metal") filling its box (set h; w
 * defaults to the page width). `params` (up to 8 numbers) reach it as P(0)…P(7). macOS only;
 * elsewhere the box draws its bg. See AGENTS.md › Shaders.
 */
export function shader(src: string, params?: number[]): Element;

/** What `activity()` returns: content beside the camera while the island is closed. */
export interface Activity {
  leading?: Element | string | null;
  trailing?: Element | string | null;
  /** Shown under the camera while the closed island is hovered: one short line. */
  detail?: Element | string | null;
  /** Higher wins the closed island when layout.json doesn't order the mods. */
  priority?: number;
  /** Width of each side in points (the island picks one by default). */
  width?: number;
}

/** How the island itself looks. Colors are theme tokens or hex; what's unset falls through
 *  to layout.json's `island.style`, then the defaults. */
export interface IslandStyle {
  /** The body's color (default: the `island` token). */
  fill?: string;
  /** Top and bottom colors, in place of `fill`. */
  gradient?: [string, string];
  border?: { width: number; color: string };
  /** A soft light around the island; radius in points (default 18). */
  glow?: { color: string; radius?: number };
  /** Bottom corners: closed (default 14, at most the camera's height) and open (default 36). */
  compactRadius?: number;
  expandedRadius?: number;
  /** The concave fillets into the screen edge (default 14, 0 for none, at most 24). */
  wings?: number;
  /** The open island's drop shadow (default true). */
  shadow?: boolean;
}

/**
 * Base class of every mod: `export default class X extends View { … }`. All methods are
 * optional.
 */
export class View {
  /** Once, when the mod loads (and after every edit of its files). */
  init?(props: Record<string, unknown>, cx: Cx): void;
  /** The closed island: what this mod shows beside the camera, or null for nothing. */
  activity?(cx: Cx): Activity | null;
  /** The open island: this mod's page. */
  expanded?(cx: Cx): Element | null;
  /** The tab icon for now, in place of mod.json's: "app:<bundle id>" (e.g. the app that's
   *  playing), "./icon.png" (drawn in colour, as an app icon), a built-in name or "./file.svg"
   *  (tinted glyphs). null keeps mod.json's. AGENTS.md › Tab icons says how they should look. */
  icon?(cx: Cx): string | null;
  /** How the island looks while this mod owns it: its activity is the closed island's, or its
   *  page is open. null leaves the look alone. Liquid Glass ignores fill and gradient. */
  style?(cx: Cx): IslandStyle | null;
  /** Before the mod unloads (an edit, or openNook quitting). */
  unmount?(cx: Cx): void;
}
